/* Living, dimensional battlefield */
.board-shell{perspective:1200px;background:linear-gradient(155deg,#535744,#292e25 48%,#171d17);border-bottom:7px solid #171d17;box-shadow:0 24px 44px #0009,0 0 0 1px #b9a96630,inset 0 1px #ffffff18}
.board-grid{transform:rotateX(12deg);transform-style:preserve-3d;box-shadow:0 18px 22px #090d0b88,0 0 0 2px #d5c58a38;overflow:hidden}
.square{transform-style:preserve-3d;box-shadow:inset 0 1px #ffffff13,inset 0 -2px #14190f20}
.square.light{background:linear-gradient(145deg,#d2c9a8 0%,#c0b791 68%,#a99f7c 100%)}
.square.dark{background:linear-gradient(145deg,#718064 0%,#58664e 68%,#45513d 100%)}
.piece{width:82%;height:88%;display:flex;align-items:flex-end;justify-content:center;isolation:isolate;border:0;border-radius:0;background:none;box-shadow:none;font-size:initial;transform-style:preserve-3d;filter:drop-shadow(0 6px 3px #16180f70)}
.piece.player,.piece.enemy{background:none;border:0;box-shadow:none;color:inherit}
.piece.selected-piece{transform:translateY(-3px) scale(1.08);filter:drop-shadow(0 0 8px #fff0a0) drop-shadow(0 7px 3px #16180f70)}
.hero-base{position:absolute;bottom:2%;left:10%;width:80%;height:23%;border-radius:50%;transform:rotateX(58deg) translateZ(2px);background:radial-gradient(ellipse at 38% 25%,#8d8a65,#494a36 65%,#282d23);border:2px solid #d5bf77;box-shadow:0 4px 0 #292b21,0 7px 9px #1119,inset 0 2px 3px #fff5}
.piece.enemy .hero-base{border-color:#c8796c;background:radial-gradient(ellipse at 38% 25%,#9b6157,#593a35 66%,#302725);box-shadow:0 4px 0 #302321,0 7px 9px #1119,inset 0 2px 3px #fff4}
.hero-figure{position:absolute;bottom:14%;left:50%;width:58%;height:76%;transform:translateX(-50%);transform-style:preserve-3d;animation:miniature-idle 2.6s ease-in-out infinite;filter:drop-shadow(0 3px 2px #17170f80)}
.hero-head{position:absolute;z-index:3;left:31%;top:3%;width:39%;aspect-ratio:1;border-radius:46% 46% 42% 42%;background:radial-gradient(circle at 34% 26%,#f0dfb0,#b99660 48%,#735338 100%);border:1px solid #e8cf87;box-shadow:inset -3px -3px 4px #352a2855,0 2px 3px #19190f66}
.hero-head:after{content:'';position:absolute;left:-20%;top:15%;width:140%;height:38%;border-radius:50% 50% 12% 12%;background:linear-gradient(110deg,#e1ca81,#76603a 78%);border-bottom:2px solid #493d2d}
.hero-torso{position:absolute;left:17%;top:35%;width:68%;height:52%;border-radius:38% 38% 20% 20%;clip-path:polygon(20% 0,80% 0,100% 100%,0 100%);background:linear-gradient(100deg,#dfd092 0%,#7d805e 34%,#454c39 72%,#292f27);border:1px solid #d3bf79;box-shadow:inset -5px 0 6px #10150f77}
.piece.enemy .hero-torso{background:linear-gradient(100deg,#e1b5a2 0%,#9c5e55 34%,#633b37 72%,#352622);border-color:#cf8476}
.hero-cape{position:absolute;z-index:-1;left:11%;top:34%;width:78%;height:52%;clip-path:polygon(16% 0,84% 0,100% 100%,0 100%);background:linear-gradient(90deg,#30362c,#606346 48%,#282d25);transform:translateZ(-4px)}
.piece.enemy .hero-cape{background:linear-gradient(90deg,#382725,#75423d 48%,#302321)}
.hero-weapon{position:absolute;z-index:4;right:-5%;top:26%;font:700 clamp(12px,1.7vw,21px)/1 serif;color:#f5dc8e;text-shadow:0 1px 3px #17130b,0 0 7px #f4d36a88;transform:translateZ(8px) rotate(-12deg)}
.piece.enemy .hero-weapon{color:#f3b39f;text-shadow:0 1px 3px #17130b,0 0 7px #e37b7188}
.hero-crest{position:absolute;z-index:5;left:50%;top:54%;transform:translate(-50%,-50%) translateZ(7px);font:700 clamp(9px,1.25vw,15px)/1 serif;color:#f3df9e;text-shadow:0 1px 3px #18170e}
.piece.enemy .hero-crest{color:#ffcfb7}
.hero-figure.warlord .hero-head:after{height:45%;background:linear-gradient(90deg,#ffe28a,#a47a2e);clip-path:polygon(0 100%,8% 0,34% 48%,50% 0,68% 48%,92% 0,100% 100%)}
.hero-figure.arcanist .hero-head{border-radius:45% 45% 12% 12%;background:linear-gradient(90deg,#b4b1ce,#686283)}
.hero-figure.arcanist .hero-cape{clip-path:polygon(20% 0,80% 0,100% 100%,0 100%);background:linear-gradient(90deg,#3b354e,#786b91,#302b40)}
.hero-figure.sentinel .hero-weapon{right:-16%;top:43%;font-size:clamp(15px,2vw,24px)}
.hero-figure.duelist .hero-weapon{right:-19%;top:35%;font-size:clamp(15px,2vw,24px)}
.hero-figure.ranger .hero-weapon{right:-15%;top:26%;font-size:clamp(14px,1.8vw,22px)}
.piece-health{z-index:7;bottom:-1%;left:17%;width:66%;height:4px}
.piece-rank{z-index:7;right:2%;top:3%}
.piece.action-move .hero-figure{animation:miniature-leap .58s cubic-bezier(.2,.8,.2,1)}
.piece.action-attack .hero-figure{animation:miniature-strike .62s cubic-bezier(.2,.8,.2,1)}
.piece.action-cast .hero-figure{animation:miniature-cast .82s ease-out}
.piece.action-guard .hero-figure{animation:miniature-guard .8s ease-out}
.piece.action-attack:after,.piece.action-cast:after,.piece.action-guard:after{content:'';position:absolute;inset:8%;border-radius:50%;pointer-events:none;animation:action-flare .65s ease-out both;z-index:6}
.piece.action-attack:after{border:3px solid #ffe29a;box-shadow:0 0 20px #ffcf69,inset 0 0 12px #fff0a0;transform:rotate(-25deg) scaleX(.55)}
.piece.action-cast:after{background:radial-gradient(circle,#fff6c966,#a999ff22 42%,transparent 70%);box-shadow:0 0 18px #b5a4ff}
.piece.action-guard:after{background:radial-gradient(circle,#e8ffca66,#a5d98022 48%,transparent 72%);box-shadow:0 0 16px #c5ee92}
@keyframes miniature-idle{0%,100%{transform:translateX(-50%) translateY(0) rotateZ(-1deg)}50%{transform:translateX(-50%) translateY(-4px) rotateZ(1deg)}}
@keyframes miniature-leap{0%{transform:translateX(-50%) translateY(0) scale(1)}38%{transform:translateX(-50%) translateY(-23%) scale(1.1)}72%{transform:translateX(-50%) translateY(2%) scale(.98)}100%{transform:translateX(-50%) translateY(0) scale(1)}}
@keyframes miniature-strike{0%{transform:translateX(-50%) rotateZ(0)}32%{transform:translateX(-24%) rotateZ(-25deg) scale(1.12)}68%{transform:translateX(12%) rotateZ(16deg)}100%{transform:translateX(-50%) rotateZ(0)}}
@keyframes miniature-cast{0%,100%{transform:translateX(-50%) rotateZ(0)}35%{transform:translateX(-50%) translateY(-10%) rotateZ(-12deg)}70%{transform:translateX(-50%) rotateZ(8deg)}}
@keyframes miniature-guard{0%,100%{transform:translateX(-50%) scale(1)}40%{transform:translateX(-50%) scale(1.2) rotateZ(-5deg)}70%{transform:translateX(-50%) scale(.96)}}
@keyframes action-flare{0%{opacity:0;transform:scale(.3) rotate(-20deg)}35%{opacity:1}100%{opacity:0;transform:scale(1.3) rotate(25deg)}}
@media(max-width:720px){.hero-weapon{font-size:clamp(11px,3vw,17px)}.hero-crest{font-size:clamp(9px,2.4vw,14px)}.board-grid{transform:rotateX(9deg)}}
@media(prefers-reduced-motion:reduce){.hero-figure{animation-duration:8s}.piece.action-move .hero-figure,.piece.action-attack .hero-figure,.piece.action-cast .hero-figure,.piece.action-guard .hero-figure{animation-duration:.01ms}}
</style>

